// Clean up the agent response for Telegram
const response = $input.item.json.output;
const chatId = $('Set Text Input').item.json.chat_id;
const userName = $('Set Text Input').item.json.user_name;
const inputText = $('Set Text Input').item.json.input_text;

// Extract actions taken by agents
let agentsCalled = [];
if (response.toLowerCase().includes('email')) agentsCalled.push('Email Agent');
if (response.toLowerCase().includes('calendar') || response.toLowerCase().includes('event')) agentsCalled.push('Calendar Agent');
if (response.toLowerCase().includes('contact')) agentsCalled.push('Contact Agent');
if (response.toLowerCase().includes('video') || response.toLowerCase().includes('youtube')) agentsCalled.push('YouTube Agent');
if (response.toLowerCase().includes('weather') || response.toLowerCase().includes('search')) agentsCalled.push('Web Agent');

// Format final response
const finalResponse = `✅ ${response}`;

return {
  json: {
    chat_id: chatId,
    response: finalResponse,
    input: inputText,
    user: userName,
    agents_called: agentsCalled.join(', '),
    timestamp: new Date().toISOString(),
    success: true
  }
};
